"""Synthetic public-key vectors and first-phase native challenge boundaries."""
import copy
import struct
import tempfile
import unittest
from logixlab import key_exchange
from logixlab.ethernetip import Endpoint, Session, symbol_path
from logixlab.server import Application
from test_ethernetip import Client

# Synthetic public key and raw-RSA result generated by an independent
# PyCryptodome public-key primitive. No native/vendor key or private key here.
MODULUS = bytes.fromhex(
    '8dcf2c47fafc252b4e777d4a847d86c5526677d2cc51ee558c548bcc85d22ed4a'
    '1b2d5e6a6020e091ecfaf279fb8522e575aa0dda7af6e724d05efe7d02139f2a'
    'b2bab0a5d508be588549fd80fc07dabb680becf0d69904bbfbaed5321a62a3af'
    'b8c71d191bdeda92e8765caace877c2283e685478313807c6b588fd85c2e39d')
NONCE = bytes(range(1, 21))
CIPHERTEXT = bytes.fromhex(
    'fdc36e095bb3c7b304d61242ee9d3c002c6bb559f23161942819dc72593046276'
    '81eed96b5ae56aef21232f06259cf286984462241b805dd4916d8ab41b617b26'
    '8e9ae1fbec7e9041479cd127e8a316b71b98a3c5287bb0916198fa7e3389477d'
    'dfa7f94ab530db03475e6c51ef368e47003f824669391e718d881f918d10600')


def offer(features=tuple((n, 1) for n in range(2, 7)), modulus=MODULUS):
    body = struct.pack('<3H', 1, 1, len(features))
    body += b''.join(struct.pack('<HH', *item) for item in features)
    body += struct.pack('<3H', 2, 0x8080, 3) + b'\1\0\1'
    body += struct.pack('<HH', 0x8081, len(modulus)) + modulus
    return struct.pack('<H', len(body)+2) + body + b'\0' * 128


class KeyExchangeTests(unittest.TestCase):
    def test_synthetic_golden_ciphertext_and_integer_orders(self):
        self.assertEqual(len(offer()), 297)
        self.assertEqual(key_exchange.challenge(offer(), nonce=NONCE), b'\x80\0' + CIPHERTEXT)
        parsed = key_exchange.parse_offer(offer())
        self.assertEqual(parsed.exponent, 65537)
        self.assertEqual(parsed.modulus, int.from_bytes(MODULUS, 'big'))

    def test_bounded_feature_subsets_preserve_order(self):
        features = ((6, 1), (2, 1))
        self.assertEqual(key_exchange.parse_offer(offer(features)).features, features)
        self.assertEqual(len(key_exchange.challenge(offer(features))), 130)

    def test_malformed_features_are_rejected_before_encryption(self):
        for features in ((), ((2, 1),)*6, ((2, 1), (2, 1)), ((9, 1),), ((2, 2),)):
            with self.subTest(features=features), self.assertRaises(key_exchange.OfferError):
                key_exchange.challenge(offer(features))

    def test_truncated_integer_and_opaque_data_rejects(self):
        raw = offer()
        for length in (0, 1, 7, 27, 29, 33, 35, 40, 100, 168, 169, 296):
            with self.subTest(length=length), self.assertRaises(key_exchange.OfferError):
                key_exchange.challenge(raw[:length])
        with self.assertRaises(key_exchange.OfferError): key_exchange.challenge(raw+b'\0')

    def test_versions_tags_lengths_boundaries_and_moduli_are_checked(self):
        for offset, value in ((0, 168), (2, 2), (4, 2), (28, 3),
                              (30, 0x8081), (32, 4), (37, 0x8080), (39, 129)):
            raw = bytearray(offer()); struct.pack_into('<H', raw, offset, value)
            with self.subTest(offset=offset), self.assertRaises(key_exchange.OfferError):
                key_exchange.challenge(raw)
        for modulus in (b'\0'*128, b'\x7F'+MODULUS[1:], MODULUS[:-1]+b'\2'):
            with self.assertRaises(key_exchange.OfferError): key_exchange.challenge(offer(modulus=modulus))
        raw = bytearray(offer()); raw[34:37] = b'\0\0\3'
        with self.assertRaises(key_exchange.OfferError): key_exchange.challenge(raw)

    def test_opaque_offer_data_does_not_imply_peer_trust(self):
        raw = offer()[:-128] + b'\xFF'*128
        self.assertEqual(key_exchange.challenge(raw, nonce=NONCE), b'\x80\0'+CIPHERTEXT)
        self.assertFalse(key_exchange.description()['peer_identity_verified'])
        self.assertFalse(key_exchange.description()['session_secret_retained'])

    def test_challenges_are_fresh_and_confirmation_stays_unsupported(self):
        with tempfile.TemporaryDirectory() as folder:
            app = Application(folder); app.command('demo', {'sample': 'ConveyorDemo'})
            endpoint = Endpoint(app, 0, False)
            session = Session(handle=1, generation=app.generation)
            before = copy.deepcopy(app.engine.memory.values)
            raw = b'\x4B\2\x20\x64\x24\1'+offer()
            try:
                a = endpoint.router.handle(raw, session); b = endpoint.router.handle(raw, session)
                self.assertEqual(a[:6], b'\xCB\0\0\0\x80\0')
                self.assertEqual(len(a), 134); self.assertNotEqual(a, b)
                self.assertEqual(endpoint.router.handle(raw,session,limit=133)[2],0x1B)
                self.assertEqual(endpoint.router.handle(raw,session,limit=134)[2],0)
                self.assertEqual(endpoint.router.handle(b'\x4C\2\x20\x64\x24\1\x14\0'+b'\0'*20, session)[2], 8)
                self.assertEqual(app.engine.memory.values, before)
                self.assertEqual(set(vars(session)), {'handle','generation','connections','peer'})
                path = b'\x20\x64\x24\1'+symbol_path('Extra')
                self.assertEqual(endpoint.router.handle(bytes((0x4B,len(path)//2))+path+offer(), session)[2], 4)
                self.assertEqual(endpoint.router.handle(b'\x4B\3\x20\x64\x24\1\x30\1'+offer(),session)[2],4)
                self.assertEqual(endpoint.router.handle(b'\x4B\2\x20\x64\x24\2'+offer(),session)[2],8)
            finally: app.close()

    def test_stopped_endpoint_does_not_advertise_exchange_support(self):
        with tempfile.TemporaryDirectory() as folder:
            app = Application(folder); app.command('demo', {'sample': 'ConveyorDemo'})
            endpoint = Endpoint(app, 0, False).start()
            try:
                self.assertTrue(endpoint.state()['key_exchange']['challenge'])
                self.assertFalse(endpoint.state()['key_exchange']['confirmation'])
                endpoint.stop(); self.assertIsNone(endpoint.state()['key_exchange'])
            finally: endpoint.stop(); app.close()

    def test_read_only_tcp_endpoint_returns_challenge_and_rejects_confirmation(self):
        with tempfile.TemporaryDirectory() as folder:
            app = Application(folder); app.command('demo', {'sample': 'ConveyorDemo'})
            endpoint = Endpoint(app, 0, False).start(); client = Client(endpoint.port)
            try:
                client.register()
                status, result = client.cip(b'\x4B\2\x20\x64\x24\1'+offer())
                self.assertEqual(status, 0); self.assertEqual(result[:6], b'\xCB\0\0\0\x80\0')
                self.assertLess(int.from_bytes(result[6:], 'little'), int.from_bytes(MODULUS, 'big'))
                status, result = client.cip(b'\x4C\2\x20\x64\x24\1\x14\0'+b'\0'*20)
                self.assertEqual((status, result), (0, b'\xCC\0\x08\0'))
            finally: client.close(); endpoint.stop(); app.close()


if __name__ == '__main__': unittest.main()
